package com.wheelwright.evidence.v2;

import com.fasterxml.jackson.databind.node.*;
import com.wheelwright.evidence.db.SqliteEvidenceStore;
import com.wheelwright.evidence.v2.portfolio.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioRepository.*;
import static org.assertj.core.api.Assertions.*;

/** Synthetic native source-shape tests; actual repository holdings fixture, no brokerage calls. */
class PortfolioOptionReferenceTest {
 @TempDir Path directory;
 final class Rig implements AutoCloseable {
  final SqliteEvidenceStore db;final PortfolioRepository repo;final String account;final ObjectNode holding;final String series;final Document original;
  Rig(boolean reportedMultiplier)throws Exception{
   db=new SqliteEvidenceStore(directory.resolve(UUID.randomUUID()+".sqlite3").toString());var accounts=new AccountDirectory(db.getConnection().getMetaData().getURL());account=accounts.bind("tt","TASTYTRADE","TEST1234");repo=new PortfolioRepository(db,JSON);holding=(ObjectNode)JSON.readTree(Files.readString(Path.of("../scripts/fixtures/tt-live-economic-observed.json"))).path("holdings").get(0).deepCopy();if(!reportedMultiplier)holding.remove("multiplier");series=holding.path("symbol").asText();var source=obj();source.set("data",obj().set("items",array().add(holding)));byte[] bytes=JSON.writeValueAsBytes(source);String artifact=retain(bytes,"API_POSITIONS","synthetic-positions.json");String at=Instant.now().toString();var snapshot=TastytradeHoldings.parse(bytes,accounts.get(account).orElseThrow(),account,artifact,BrokerageArtifacts.sha(bytes),new PositionSnapshot.Observation("TASTYTRADE","PRODUCTION",UUID.randomUUID().toString(),at,at,"synthetic-source-test","ACCOUNT_POSITIONS"));new PositionReadService(db,JSON).admit(snapshot);new PortfolioSources(repo,JSON,accounts).refresh(Set.of(account));original=repo.list(Kind.CONSTRUCTION,Set.of(account)).getFirst();
  }
  String retain(byte[] bytes,String type,String filename)throws Exception{
   String artifact=UUID.randomUUID().toString();try(var c=repo.connection()){
    try(var q=c.prepareStatement("INSERT INTO brokerage_artifact VALUES (?,?,?,?,?,?,?)")){q.setString(1,account);q.setString(2,artifact);q.setString(3,BrokerageArtifacts.sha(bytes));q.setString(4,"application/json");q.setInt(5,bytes.length);q.setBytes(6,bytes);q.setString(7,Instant.now().toString());q.executeUpdate();}
    try(var q=c.prepareStatement("INSERT INTO brokerage_import VALUES (?,?,?,?,?,?,'PENDING','synthetic backend source')")){q.setString(1,account);q.setString(2,UUID.randomUUID().toString());q.setString(3,artifact);q.setString(4,filename);q.setString(5,type);q.setString(6,Instant.now().toString());q.executeUpdate();}
   }return artifact;
  }
  ObjectNode chain(String type,String shares){var group=obj().put("underlying-symbol",holding.path("underlying-symbol").asText()).put("option-chain-type",type).put("shares-per-contract",shares);group.set("symbols",array().add(series));group.set("deliverables",array().add(obj().put("deliverable-type","Shares").put("instrument-type","Equity").put("symbol",holding.path("underlying-symbol").asText()).put("amount",shares)));var root=obj().put("context","/option-chains/{symbol}/compact");root.set("data",obj().set("items",array().add(group)));return root;}
  void admit(ObjectNode root)throws Exception{String artifact=retain(JSON.writeValueAsBytes(root),"API_OPTION_CHAIN","tastytrade-option-chain-XLF.json");try(var c=repo.connection()){c.setAutoCommit(false);try{new PortfolioOptionReferenceSources(repo).admit(c,account,artifact,"XLF",Set.of(series));new PortfolioReferenceEnrichment(repo).apply(c,account,Instant.now());c.commit();var artifacts=new BrokerageArtifacts(db.getConnection().getMetaData().getURL(),JSON,new PositionReadService(db,JSON));assertThat(artifacts.sourceScopes(account,"tastytrade-option-chain-XLF.json",JSON.writeValueAsBytes(root)).established()).isTrue();}catch(Exception e){c.rollback();throw e;}}}
  Document current()throws Exception{return repo.get(repo.list(Kind.POSITION,Set.of(account)).getFirst().value().at("/currentConstruction/href").asText()).orElseThrow();}
  public void close()throws Exception{db.close();}
 }
 @Test void independentReferenceAndCustodyFactsComposeWithoutRewritingHistoryOrInventingOpening()throws Exception{
  try(var r=new Rig(true)){String position=r.original.value().at("/position/href").asText();r.admit(r.chain("Standard","100.0"));var current=r.current();assertThat(current.uri()).isNotEqualTo(r.original.uri());assertThat(current.value().at("/predecessor/href").asText()).isEqualTo(r.original.uri());assertThat(repoValue(r,r.original.uri())).isEqualTo(r.original.value());assertThat(current.value().at("/position/href").asText()).isEqualTo(position);var leaf=leaves(current.value().path("composition")).getFirst();assertThat(number(leaf.at("/terms/multiplier"))).isEqualByComparingTo(number(r.holding.path("multiplier")));var reference=r.repo.get(leaf.at("/instrument/href").asText()).orElseThrow().value();assertThat(reference.at("/option/multiplier").isNull()).isTrue();assertThat(reference.toString()).doesNotContain(r.account,"/v2/artifacts/","ACCOUNT_SOURCE");var geometry=PortfolioMath.payoff(current.value(),Instant.now());assertThat(geometry.at("/geometry/valueKind").asText()).isEqualTo("TERMINAL_VALUE");assertThat(geometry.at("/geometry/breakEvenPrices")).isEmpty();var nativeRows=JSON.readTree(Files.readString(Path.of("../scripts/fixtures/tt-live-economic-observed.json"))).path("instruments");com.fasterxml.jackson.databind.JsonNode nativeContract=null;for(var row:nativeRows)if(row.path("symbol").asText().equals(r.series))nativeContract=row;assertThat(nativeContract).isNotNull();BigDecimal strike=new BigDecimal(nativeContract.path("strike-price").asText());assertThat(number(leaf.at("/terms/strike"))).isEqualByComparingTo(strike);for(BigDecimal spot:List.of(BigDecimal.ZERO,strike.subtract(BigDecimal.ONE),strike,strike.add(BigDecimal.TEN))){com.fasterxml.jackson.databind.JsonNode selected=null;for(var segment:geometry.at("/geometry/segments"))if(spot.compareTo(number(segment.path("lower")))>=0&&(segment.path("upper").isNull()||spot.compareTo(number(segment.path("upper")))<0))selected=segment;assertThat(selected).isNotNull();BigDecimal expected=strike.subtract(spot).max(BigDecimal.ZERO).multiply(new BigDecimal(r.holding.path("quantity").asText())).multiply(number(r.holding.path("multiplier")));assertThat(number(selected.path("slope")).multiply(spot).add(number(selected.path("intercept")))).isEqualByComparingTo(expected);}var evaluation=PortfolioMath.evaluate(current.value(),Map.of(),Instant.now());assertThat(evaluation.at("/openingCashFlow/value").isNull()).isTrue();assertThat(evaluation.at("/timeline/openedAt").isNull()).isTrue();String first=current.uri();new PortfolioSources(r.repo,JSON,new AccountDirectory(r.db.getConnection().getMetaData().getURL())).refresh(Set.of(r.account));assertThat(r.current().uri()).isEqualTo(first);
   capture(current.uri(),"Construction",current.value());capture(reference.at("/self/href").asText(),"Instrument",reference);
  }
 }
 @Test void deliverableCountDoesNotManufactureAnUnreportedPriceMultiplier()throws Exception{try(var r=new Rig(false)){r.admit(r.chain("Standard","100"));var terms=leaves(r.current().value().path("composition")).getFirst().path("terms");assertThat(terms.path("multiplier").isNull()).isTrue();assertThat(PortfolioMath.payoff(r.current().value(),Instant.now()).path("geometry").isNull()).isTrue();}}
 @Test void adjustedDeliverablesStayInspectableWithoutStandardIntrinsicGeometry()throws Exception{try(var r=new Rig(true)){r.admit(r.chain("NonStandard","12"));var current=r.current();var terms=leaves(current.value().path("composition")).getFirst().path("terms");assertThat(terms.path("adjustment").asText()).isEqualTo("ADJUSTED");assertThat(number(terms.at("/deliverable/0/quantity"))).isEqualByComparingTo("12");assertThat(PortfolioMath.payoff(current.value(),Instant.now()).path("geometry").isNull()).isTrue();capture(current.uri(),"Construction",current.value());}}
 @Test void conflictingOrAmbiguousSourceCannotPartiallyOverwritePriorReferenceOrConstruction()throws Exception{
  for(String defect:List.of("deliverable","foreign","missing","duplicate"))try(var r=new Rig(true)){var root=r.chain("Standard","100");var group=(ObjectNode)root.at("/data/items/0");switch(defect){case "deliverable"->((ObjectNode)group.at("/deliverables/0")).put("amount","12");case "foreign"->group.put("underlying-symbol","SPY");case "missing"->group.set("symbols",array());default->((ArrayNode)root.at("/data/items")).add(group.deepCopy());}assertThatThrownBy(()->r.admit(root)).isInstanceOf(IllegalArgumentException.class);assertThat(r.current().value()).isEqualTo(r.original.value());var leaf=leaves(r.original.value().path("composition")).getFirst();assertThat(r.repo.get(leaf.at("/instrument/href").asText()).orElseThrow().value().path("option").isNull()).isTrue();}
 }
 static ObjectNode repoValue(Rig r,String uri)throws Exception{return r.repo.get(uri).orElseThrow().value();}
 static void capture(String uri,String schema,ObjectNode body)throws Exception{var out=Path.of("build/portfolio-responses");Files.createDirectories(out);var value=obj().put("path",uri).put("schema",schema).put("caller","synthetic-source-reference-test");value.set("body",body);Files.writeString(out.resolve(UUID.randomUUID()+".json"),value.toString());}
}
